// === Tab: mySketch ===
//
// From this great Argonaut video: https://youtu.be/qlfh_rv6khY
//

let wormCount = 150, hop;
let worm = [], dir = [], dest = [], thick= [], bkg;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1)
	generate();
}

function mouseClicked() {
	generate();
}

function generate() {
	hop = max(width, height) / 3;
	let cent = createVector (width/2,height/2);
	let displace = createVector (cent.mag()*1.1,0);
	for (let i = 0; i < wormCount; i++) {
		const n = floor (random(5,20));
		const separation = random(10,40);
		thick[i] = arcThickness (n, separation, random(PI/4,PI/6));
		worm[i] = new Spine({n, separation});
		let p = cent.copy().add(displace.rotate(random(TWO_PI)));
		worm[i].setNode(0,p.x, p.y);
		dest[i] = createVector(random(width), random(height));
		dir [i] = createVector(random(2,5),0);
		dir [i].rotate(random(TWO_PI))
		worm[i].color = color(random(255),random(255),random(255),20)
	}
	noStroke();
	bkg = random([0, 30, 220,255]);
	background(bkg);
}

function draw() {
	background(bkg,10);
	t = frameCount / 100;
	for (let i = 0; i < wormCount; i++) {
		w = worm[i];
		fill(w.color);
		w.draw(thick[i]);
		var p = w.node[0];
		let d = p.dist(dest[i]); 
		if (d < 4 || random()<0.01) {
			const delta = createVector (hop,0);
			delta.rotate(random(TWO_PI));
			const newx = constrain(p.x+delta.x,0,width);
			const newy = constrain(p.y+delta.y,0,height);
			dest[i] = createVector (newx,newy);
		}
		let v = dest[i].copy().sub(p);
		let ang = v.angleBetween(dir[i]);
		dir[i].rotate(constrain(-ang,-PI/90, PI/90));
		let q = p.add(dir[i]);
		if (q.dist(p)<d) w.setNode(0,q.x,q.y)
	}
}

function arcThickness(n,separation,angle=PI/4) {
	let dAngle = angle*2/(n-1);
	let r = separation * n / 2;
	var p = [];
	let a0 = -PI/2-angle;
	for (let i = 0; i < n; i++) {
		let a = a0 + dAngle*i;
		p.push (r*sin(a))
	}
	return (i) => p[i]-p[0];
}

class Spine {
	constructor ({n=10,separation=20,bendMax=PI/6}={}) {
		let node = [];
		for (let i =0; i<n;i++) node.push(createVector(i*separation,0));
		Object.assign(this,{n,separation,bendMax,node});
	}
	relaxRight(i, u) {
		if (i+1 < this.n) { 
			var v = this.node[i+1].copy().sub(this.node[i]);
			// let u = this.node[i].copy().sub(this.node[i-1])
			var ang = u.angleBetween(v);
			if (ang < -this.bendMax) v.rotate(-ang-this.bendMax)
			else if (ang > this.bendMax) v.rotate(-ang+this.bendMax)
			v.setMag(this.separation);
			this.node[i+1] = this.node[i].copy().add(v);
			this.relaxRight(i+1, v)
		}
	}
	relaxLeft(i, u) {
		if (i > 0) { 
			var v = this.node[i-1].copy().sub(this.node[i]);
			//let u = this.node[i].copy().sub(this.node[i+1]);
			var ang = u.angleBetween(v);
			if (ang < -this.bendMax) v.rotate(-ang-this.bendMax)
			else if (ang > this.bendMax) v.rotate(-ang+this.bendMax)
			v.setMag(this.separation);
			this.node[i-1] = this.node[i].copy().add(v);
			this.relaxLeft(i-1,v)
		}
	}
	closest (x,y) {
		let {node,n} = this;
		let best_d = 1e10;
		let best_i = 0;
		var p = createVector(x,y);
		for (let i = 0; i < n; i++) {
			var d = p.dist(node[i]);
			if (d<best_d) {
				best_d = d;
				best_i = i;
			}
		}
		return best_i;
	}
	setNode(i,x,y) {
		let {n,node} = this;
		let u;
		if (i > 0) {
			if (i+1 < n) {
				u = node[i+1].copy().sub(node[i-1]);
			}
			else {
				u = node[i].copy().sub(node[i-1]);
			}
		} 
		else {
			u = node[i+1].copy().sub(node[i]);
		}
		this.node[i] = createVector(x,y);
		this.relaxRight(i,createVector(u.x,u.y));
		this.relaxLeft(i,createVector(-u.x,-u.y));
	}
	draw(thickness=(i)=>10) {
		const {n,node} = this;
		let left = [], right = [];
		for (let i = 0; i < n; i++) {
			var p = i > 0 ? node[i-1] : node[i];
			var q = node[i];
			var r = i < n-1 ? node[i+1] : node[i];
			var v = r.copy().sub(p).setMag(thickness(i)).rotate(PI/2);
			left.push (q.copy().add(v));
			right.push (q.copy().sub(v));
		}
		right.reverse();
		beginShape()
		//for (let p of right.slice(-3)) curveVertex (p.x,p.y);
		var a = left[0];
		let b = right[0];
		vertex(a.x,a.y);vertex(a.x,a.y); 
		for (let p of left) curveVertex(p.x,p.y);
		vertex (b.x, b.y);vertex (b.x, b.y);
		for (let p of right) curveVertex(p.x,p.y);
		vertex(a.x,a.y); 
		endShape(CLOSE);
	}
}

